const V=x=>{if(x==null)return"";if(typeof x==="object"){if(x.p)return pchip(x.p);if(x.pill)return pill(H(x.pill),x.cls);if(x.h)return san(x.h);return H(JSON.stringify(x))}return H(x)};
const pillT=(t,c)=>`<span class="pill ${c||"mute"}">${H(t)}</span>`;
const okChip=(ok,t)=>`<span class="cx-pc ${ok?"ok":"no"}">${ok?"Allowed":"Blocked"}</span> ${H(t)}`;
const ownHTML=o=>{if(!o)return"";const w=o.who||"";const p=who(w);return`<span class="cx-own k-${o.kind}">${p?avatar(w,{size:20}):`<i class="cx-ownic" aria-hidden="true">${o.kind==="auto"||o.kind==="robot"?"R":o.kind==="gate"?"G":"P"}</i>`}<span>${H(w)}</span><small>${OWN[o.kind]||""}</small></span>`};
const aiChipL=(l,x)=>aiChip(Object.assign({model:l.model,conf:l.conf,title:l.title||"How I answered",note:l.note,src:l.src,guards:l.guards},x||{}));
function guardChips(pols){return(pols||[]).map(n=>`<span class="cx-pc ${n.ok?"ok":"no"}" title="${H(n.n+": "+n.txt)}">${H(n.pol)}</span>`).join("")}

/* --- plan card --- */
function stepHTML(a,s,i){const sp=STP[s.status]||STP.queued;const tool=s.tool?TBY(s.tool):null;const r=s.res;let extra="";
 if(s.kind==="gate"&&s.status==="awaiting"){const ap=s.gate.who;const mine=ap===ME_NAME;const dl=!mine&&delegation(ap);extra=`<div class="cx-gate"><span class="muted small">${H(s.gate.why)}</span><div class="row">${mine?`<button class="btn primary" data-cx-do="gate:${a.id}:${s.id}:approved:me">Approve</button><button class="btn" data-cx-do="gate:${a.id}:${s.id}:rejected:me">Reject</button>`:`${dl&&dl.verified?`<button class="btn" data-cx-do="gate:${a.id}:${s.id}:approved:deleg" title="You hold a verified delegation from ${H(ap)}">Approve for ${H(firstOf(ap))} (delegate)</button>`:""}<button class="btn quiet" data-cx-do="gate:${a.id}:${s.id}:approved:demo" title="Prototype only: records the decision as if ${H(ap)} made it">Demo: ${H(firstOf(ap))} approves</button><button class="btn quiet" data-cx-do="gate:${a.id}:${s.id}:rejected:demo">Demo: rejects</button><button class="btn quiet" data-cx-do="nudge:${a.id}:${s.id}">Nudge</button>`}</div></div>`}
 else if(s.kind==="gate"&&s.gate.at)extra=`<div class="muted small">${s.gate.st==="approved"?"Approved":"Rejected"} by ${H(s.gate.by)} at ${H(s.gate.at)}</div>`;
 if(s.kind==="act"&&s.reqId){const rq=ST.reqs.find(x=>x.id===s.reqId);if(rq&&rq.gates.length)extra+=`<div class="cx-sub">${rq.gates.map((g,gi)=>`<div class="cx-subrow"><span>${g.st==="approved"?"Approved":g.st==="rejected"?"Rejected":"Waiting"}: ${pchip(g.who)}<small class="muted"> ${H(g.why)}</small></span>${g.st==="pending"?(g.who===ME_NAME?`<button class="btn primary" data-cx-do="reqgate:${rq.id}:${gi}:approved:me">Approve</button>`:`<button class="btn quiet" data-cx-do="reqgate:${rq.id}:${gi}:approved:demo">Demo: approve</button>`):""}</div>`).join("")}</div>`}
 if(s.sub&&s.sub.length)extra+=`<details class="cx-subplan"><summary>Sub-plan, ${s.sub.length} stages</summary><ol>${s.sub.map(x=>`<li>${H(x)}</li>`).join("")}</ol></details>`;
 if(s.err)extra+=`<div class="cx-err" role="alert">${H(s.err)}</div>`;
 if(r&&r.summary&&s.status==="done")extra+=`<div class="muted small">${H(r.summary)}${s.undone?" · undone":""}</div>`;
 if((s.blocked||[]).length&&s.status!=="done")extra+=`<div class="cx-err">${H(s.blocked[0])}</div>`;
 return`<li class="cx-step st-${s.status}" ${s.status==="running"?'aria-busy="true"':""}><span class="cx-dot" aria-hidden="true"></span><div class="cx-sbody"><div class="cx-shead"><b>${H(s.label)}</b>${pillT(sp[0],sp[1])}${s.kind==="act"&&RANK[s.risk||"low"]>1?pillT(RISK[s.risk].n+" risk",RISK[s.risk].cls):""}</div><div class="cx-sown">${ownHTML(s.owner)}${tool&&tool.int?'<span class="pill mute">internal step</span>':""}</div>${extra}</div></li>`}
function planHTML(a,o){o=o||{};if(!a)return`<div class="cx-plan muted">This plan is no longer available.</div>`;const ap=ACTP[a.status]||ACTP.planned;const done=a.steps.filter(s=>DONE.includes(s.status)).length;const pct=Math.round(done/a.steps.length*100);
 const rk=RISK[a.risk||"low"];const tools=a.steps.filter(s=>s.kind==="act");const gates=a.steps.filter(s=>s.kind==="gate");
 const btn=(c,l,cls)=>`<button class="btn ${cls||""}" data-cx-do="${c}:${a.id}">${l}</button>`;
 let foot="";if(a.status==="planned")foot=btn("plan-run","Approve and run","primary")+btn("plan-edit","Edit")+btn("plan-cancel","Cancel","quiet");
 else if(a.status==="suggested")foot=btn("plan-ask","Switch to ask before acting","primary")+btn("plan-cancel","Dismiss","quiet");
 else if(a.status==="running"||a.status==="awaiting")foot=btn("plan-cancel","Cancel the rest","quiet");
 else if(a.status==="done"||a.status==="undone"){if(undoable(a))foot=btn("plan-undo","Undo");foot+=btn("plan-open","Open in Activities","quiet")}
 else if(a.status==="failed")foot=btn("plan-retry","Retry","primary")+btn("plan-escalate","Hand to a person")+btn("plan-undo","Undo what ran","quiet");
 else if(a.status==="blocked"){const roles=Object.keys(ROLE_CAPS).filter(k=>tools.every(s=>{const t=TBY(s.tool);return!t||!t.perm||capsOf(k).includes(t.perm)}));foot=roles.filter(k=>k!==S.persona).slice(0,2).map(k=>`<button class="btn" data-cx-do="role:${k}">View as ${H(PERSONAS[k].n)}</button>`).join("")+btn("plan-escalate","Hand to a person")+btn("plan-cancel","Dismiss","quiet")}
 else if(a.status==="cancelled")foot=btn("plan-open","Open in Activities","quiet");
 const par=a.params&&Object.keys(a.params).length?`<details class="cx-par"><summary>Parameters</summary><dl class="kv">${Object.keys(a.params).filter(k=>a.params[k]!==""&&a.params[k]!=null&&k!=="count").map(k=>`<dt>${H(k)}</dt><dd>${V(typeof a.params[k]==="boolean"?(a.params[k]?"Yes":"No"):a.params[k])}</dd>`).join("")}</dl></details>`:"";
 const pol=(a.pols&&a.pols.length)?`<details class="cx-par"><summary>Guardrails checked ${guardChips(a.pols)}</summary><ul class="cx-pol">${a.pols.map(n=>`<li>${okChip(n.ok,n.pol+" "+n.n+": "+n.txt)}</li>`).join("")}</ul></details>`:"";
 return`<div class="cx-plan st-${a.status}" data-cx-act="${a.id}" ${o.compact?"":""}><div class="cx-phead"><div><b class="cx-ptitle">${H(a.title)}</b><div class="muted small">${a.steps.length} step${a.steps.length===1?"":"s"} · ${tools.length} action${tools.length===1?"":"s"} · ${gates.length} approval${gates.length===1?"":"s"} from people${a.onBehalf?` · on behalf of <b>${H(a.onBehalf)}</b>`:""}</div></div><div class="row">${pillT(ap[0],ap[1])}${pillT(rk.n+" risk",rk.cls)}</div></div>
 <div class="cx-prog" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100" aria-label="Plan progress"><u style="width:${pct}%"></u></div>
 <ol class="cx-steps2">${a.steps.map((s,i)=>stepHTML(a,s,i)).join("")}</ol>${pol}${par}
 <div class="cx-pfoot"><div class="row">${foot}</div><div class="row">${a.lin?aiChipL(a.lin,{title:"AI lineage for this plan"}):""}<span class="pill metric" title="Confidence of the planner in the match and the parameters">${Math.round((a.conf||.8)*100)}% sure</span></div></div>${o.log&&a.log.length?`<details class="cx-par"><summary>Activity log, ${a.log.length} entries</summary><ul class="cx-log">${a.log.map(l=>`<li><span class="muted">${H(l.t)}</span> ${H(l.tx)}</li>`).join("")}</ul></details>`:""}</div>`}

/* --- request tracker --- */
function trackHTML(spec){let r=null,real=null;if(spec.id)r=ST.reqs.find(x=>x.id===spec.id);if(spec.real)real=G(()=>window.REQREG.find(x=>x.id===spec.real),null);if(!r&&!real)return`<div class="cx-track muted">Request ${H(spec.id||spec.real||"")} not found.</div>`;
 if(real){const st=real.state||"pending";const stage=/deployed|delivered|decom/.test(st)?4:/fulfill|approved/.test(st)?3:/pending/.test(st)?2:1;const sit=G(()=>real.w&&real.w[0]?real.w[0].n:"",""),stp=real.stepN||"";const pend=Object.values(real.ap||{}).filter(a=>a.st==="pending");
  return`<div class="cx-track" data-cx-req="${H(real.id)}"><div class="cx-thead"><b>${H(real.id)}</b><span class="muted">${H(real.service||"")}</span>${pillT(st,/rejected|cancel/.test(st)?"bad":/pending/.test(st)?"warn":"good")}</div>${stagesHTML(stage,["Submitted","Approvals","Fulfillment","Delivered"],/rejected|cancel/.test(st))}<p class="cx-sit">${sit?`Sitting with <b>${H(sit)}</b>${stp?" on "+H(stp):""}.`:"Not waiting on anyone."}${real.sl!=null?` <b>${real.sl}%</b> of the SLA is used${real.sl>=75?", so it is at risk":""}.`:""}</p>${pend.length?`<div class="cx-sub">${pend.map(a=>`<div class="cx-subrow"><span>Approval pending: ${pchip(a.who)}</span></div>`).join("")}</div>`:""}<div class="row"><button class="btn" data-cx-cmd="reqopen:${H(real.id)}">Open request</button></div></div>`}
 const stage=reqProgress(r),pend=r.gates.filter(g=>g.st==="pending");const sit=r.state==="Approvals"?pend.map(g=>g.who).join(" and "):r.state==="Fulfillment"?({laptop:"Northwind Managed Services",phone:"Northwind Managed Services",software:"the endpoint team",monitor:"Facilities",access:"the identity team",aiaccess:"the AI gateway"}[r.item]||"fulfillment"):"";
 return`<div class="cx-track" data-cx-req="${H(r.id)}"><div class="cx-thead"><b>${H(r.id)}</b><span>${H(r.title)}</span>${pillT(r.state,r.state==="Rejected"||r.state==="Cancelled"?"bad":r.state==="Delivered"?"good":r.state==="Approvals"?"warn":"info")}</div><div class="muted small">For ${pchip(r.for)} · requested by ${H(r.by)} · ${r.cost?mon(r.cost):"no charge"} · ${H(r.via)}</div>${stagesHTML(stage,REQ_STAGES,r.state==="Rejected"||r.state==="Cancelled")}<p class="cx-sit">${sit?`Now sitting with <b>${H(sit)}</b>. Expected delivery about ${r.eta} business days after approval.`:r.state==="Delivered"?"Delivered.":r.state==="Rejected"?"Rejected. See the log.":"Closed."}</p>${r.gates.length?`<div class="cx-sub">${r.gates.map((g,gi)=>`<div class="cx-subrow"><span>${g.st==="approved"?"Approved":g.st==="rejected"?"Rejected":"Waiting"}: ${pchip(g.who)}<small class="muted"> ${H(g.why)}</small></span>${g.st==="pending"&&r.state==="Approvals"?(g.who===ME_NAME?`<button class="btn primary" data-cx-do="reqgate:${r.id}:${gi}:approved:me">Approve</button>`:(delegation(g.who).verified?`<button class="btn" data-cx-do="reqgate:${r.id}:${gi}:approved:deleg">Approve as delegate</button>`:`<button class="btn quiet" data-cx-do="reqgate:${r.id}:${gi}:approved:demo">Demo: approve</button>`)):""}</div>`).join("")}</div>`:""}<details class="cx-par"><summary>History, ${r.log.length} entries</summary><ul class="cx-log">${r.log.map(l=>`<li><span class="muted">${H(l.t)}</span> ${H(l.tx)}</li>`).join("")}</ul></details>${r.state==="Fulfillment"?`<div class="row"><button class="btn quiet" data-cx-do="deliver:${r.id}">Demo: mark delivered</button></div>`:""}</div>`}
function stagesHTML(n,labels,bad){return`<ol class="cx-stages" aria-label="Stages">${labels.map((l,i)=>`<li class="${i+1<n?"past":i+1===n?"now":""}${bad&&i+1===n?" bad":""}"><i></i><span>${H(l)}</span></li>`).join("")}</ol>`}

/* --- generic cards --- */
function cardHTML(c,m){if(!c)return"";switch(c.t){
 case"plan":return planHTML(CX.actById(c.id));
 case"form":return formHTML2(ST.forms[c.id]);
 case"tracker":return trackHTML(c);
 case"result":{const kv=(c.kv||[]).length?`<dl class="kv">${c.kv.map(k=>`<dt>${H(k[0])}</dt><dd>${V(k[1])}</dd>`).join("")}</dl>`:"";const tb=c.tbl?`<div class="tscroll"><table class="cx-tbl"><thead><tr>${c.tbl.h.map(h=>`<th>${H(h)}</th>`).join("")}</tr></thead><tbody>${c.tbl.r.map(r=>`<tr>${r.map(x=>`<td>${V(x)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`:"";return`<div class="cx-res tone-${c.tone||"good"}"><div class="cx-rt"><b>${H(c.title)}</b>${c.sub?`<div class="muted small">${H(c.sub)}</div>`:""}</div>${kv}${tb}${(c.btns||[]).length?`<div class="row">${c.btns.map(b=>`<button class="btn" data-cx-cmd="${H(b.d)}">${H(b.l)}</button>`).join("")}</div>`:""}</div>`}
 case"table":return`<div class="cx-res"><div class="cx-rt"><b>${H(c.title||"")}</b></div><div class="tscroll"><table class="cx-tbl"><thead><tr>${c.h.map(h=>`<th>${H(h)}</th>`).join("")}</tr></thead><tbody>${c.r.map(r=>`<tr>${r.map(x=>`<td>${V(x)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>${c.note?`<p class="muted small">${H(c.note)}</p>`:""}${(c.btns||[]).length?`<div class="row">${c.btns.map(b=>`<button class="btn" data-cx-cmd="${H(b.d)}">${H(b.l)}</button>`).join("")}</div>`:""}</div>`;
 case"people":return`<div class="cx-people">${c.names.map(n=>{const r=who(n)||{};const wl=G(()=>workload(n),null);return`<div class="cx-pc2">${avatar(n,{size:40})}<div class="cx-pcb"><div class="row">${pchip(n,{role:1})}${r.kind?kindPill(r.kind):""}${wl?`<span class="pill ${wl.pct>95?"bad":wl.pct>75?"warn":"good"}">Load ${wl.pct}%</span>`:""}</div><div class="muted small">${H((c.why||{})[n]||"")}</div></div></div>`}).join("")}</div>`;
 case"lr":return`<div class="cx-lr">${(c.groups||[]).map(g=>`<details ${g.rows.length&&c.groups.length<3?"open":""}><summary>${H(g.label)} <span class="pill mute">${g.rows.length}</span></summary>${g.rows.map(r=>{const k=r.go?cb(r.go):"";return`<div class="cx-lrr">${k?`<button class="cx-link" data-cx-cb="${k}">${H(r.t)}</button>`:`<span>${H(r.t)}</span>`}<small class="muted">${H(r.sub||"")}</small></div>`}).join("")}</details>`).join("")||'<p class="muted small">Nothing assigned.</p>'}</div>`;
 case"btnrow":return`<div class="row cx-btnrow">${c.btns.map(b=>`<button class="btn" data-cx-cmd="${H(b.d)}">${H(b.l)}</button>`).join("")}</div>`;
 case"note":return`<p class="muted small cx-note">${san(c.html)}</p>`;
 case"std":return`<div class="row">${(c.keys||[]).map(k=>stdChip(k,c.detail)).join("")}</div>`;
 case"metricrow":return`<div class="cx-metrics">${(c.ids||[]).filter(id=>METRICS[id]).map(id=>{const m=METRICS[id],st=G(()=>mstat(m),"good");return`<div class="cx-mt"><div class="row">${fchip(id)}<span class="pill ${stCls(st)}">${st==="good"?"On trend":"Off trend"}</span></div><div class="row"><b class="num" data-role="metric">${H(mfmt(m))}</b><span class="muted small">target ${H(mfmt(m,m.tgt))}</span></div>${spark(m.tr,200,34,col(st==="good"?"--good-f":st==="warn"?"--warn-f":"--bad-f"))}</div>`}).join("")}</div>`;
 case"cites":return`<div class="cx-cites"><div class="eyebrow">Sources</div>${(c.items||[]).map((x,i)=>{const k=x.go?cb(x.go):"";return`<div class="cx-cite"><span class="cx-cn">${i+1}</span>${k?`<button class="cx-link" data-cx-cb="${k}">${H(x.t)}</button>`:`<span>${H(x.t)}</span>`}<small class="muted">${H(x.src||"")}</small></div>`}).join("")||'<p class="muted small">No sources.</p>'}</div>`;
 case"chart":return chartHTML(c);
 case"banner":return bannerHTML(c.who,c.dl);
 case"pack":return packSecHTML(subjectPack(c.who).find(s=>s.key===c.sec),c.who);
 default:return""}}
function chartHTML(c){const d=c.data||[];if(!d.length)return`<div class="cx-res"><b>${H(c.title)}</b><p class="muted small">No data in the current volume.</p></div>`;const mx=Math.max.apply(null,d.map(x=>+x[1]||0))||1;
 if(c.line){const vals=d.map(x=>+x[1]);return`<div class="cx-res"><div class="cx-rt"><b>${H(c.title)}</b></div><div class="cx-line">${spark(vals,420,90,col("--metric-f"))}</div><div class="row sp muted small"><span>${H(d[0][0])}</span><span>${H(d[d.length-1][0])}</span></div>${c.note?`<p class="muted small">${H(c.note)}</p>`:""}<p class="muted small">Fields: <code>${H(c.fields||"")}</code>. Line is the metric value for each period; the dot is the latest.</p></div>`}
 return`<div class="cx-res"><div class="cx-rt"><b>${H(c.title)}</b><div class="muted small">Bar length is the number of ${H(c.unit||"records")}. Fields used: <code>${H(c.fields||"")}</code></div></div><div class="cx-bars">${d.map(x=>`<div class="cx-bar" title="${H(x[0])}: ${H(x[1])} ${H(c.unit||"")}"><span class="cx-bl">${H(x[0])}</span><i><u style="width:${Math.round((+x[1]||0)/mx*100)}%"></u></i><b class="num">${H(x[1])}</b></div>`).join("")}</div>${c.note?`<p class="muted small">${H(c.note)}</p>`:""}<div class="row">${(c.btns||[]).filter(b=>b.d!=="go:flw_viz"||SCREENS.some(s=>s[0]==="flw_viz")).map(b=>`<button class="btn" data-cx-cmd="${H(b.d)}">${H(b.l)}</button>`).join("")}</div></div>`}
function allowMatrix(who_,c){const out={ok:[],gate:[],no:[]};LIVE().filter(t=>t.write&&!t.int&&!t.plan||t.plan).forEach(t=>{const p={who:who_,target:who_,name:who_};const k=check(t,p,c);if(!k.allow)out.no.push({t,why:k.block[0]});else if(k.gates.length||t.confirm==="always"||t.risk==="high")out.gate.push({t,g:k.gates});else out.ok.push({t})});return out}
function bannerHTML(name,dl){dl=dl||delegation(name);const r=who(name)||{};const c=ctxNow();const m=allowMatrix(name,c);return`<div class="cx-banner ${dl.verified?"ok":"no"}" role="note"><div class="cx-bh">${avatar(name,{size:36})}<div><b>Acting on behalf of ${H(name)}</b> <span class="muted">(you are ${H(firstOf(ME_NAME))}; ${dl.verified?"delegation verified":"delegation NOT verified"})</span><div class="muted small">${H(dl.basis)}</div></div></div><div class="row"><span class="pill good">${m.ok.length} allowed</span><span class="pill warn">${m.gate.length} need approval</span><span class="pill bad">${m.no.length} blocked</span>${r.kind?kindPill(r.kind):""}${hasCap("hr.read")?"":'<span class="pill mute" title="Compensation, performance and time off reasons are hidden for your role">HR data redacted</span>'}</div>${dl.verified?`<div class="muted small">Scope: ${H(dl.scope)}</div>`:`<div class="cx-err">${H(dl.needs)}</div><div class="row"><button class="btn" data-cx-do="deleg-request:${H(name)}">Request delegation</button></div>`}</div>`}
function packSecHTML(s,name){if(!s)return"";if(s.redacted)return`<div class="cx-sec"><div class="cx-sech"><b>${H(s.label)}</b><span class="cx-redact" title="Policy G4 hides sensitive HR data unless your role holds the HR data permission">Redacted</span></div><p class="muted small">${H(s.note)}</p></div>`;
 return`<details class="cx-sec" ${s.n&&s.n<=4?"open":""}><summary><b>${H(s.label)}</b> <span class="pill mute">${s.n}</span>${s.redactNote?'<span class="cx-redact" title="The reason for time off is hidden for your role">Reasons redacted</span>':""}</summary>${s.rows.slice(0,8).map(x=>{const k=x.go?cb(x.go):"";return`<div class="cx-lrr">${k?`<button class="cx-link" data-cx-cb="${k}">${H(x.t)}</button>`:H(x.t)}<small class="muted">${H(x.sub||"")}</small></div>`}).join("")||'<p class="muted small">None on record.</p>'}${s.n>8?`<p class="muted small">${s.n-8} more. Ask “show all ${H(s.label.toLowerCase())}”.</p>`:""}</details>`}

/* --- inline forms --- */
const FL={};
function dlId(t){return t==="person"?"cxDlPeople":t==="service"?"cxDlSvc":t==="rec"?"cxDlRec":""}
function fieldH(f,v,err,fid,pre){const id=fid+"_"+f.k,val=v==null?"":v;const opts=typeof f.opts==="function"?f.opts():f.opts||[];const dat=`data-cx-f="${fid}:${f.k}" id="${id}"`;let inner="";
 switch(f.type){
  case"longtext":inner=`<textarea class="fin" rows="2" ${dat} placeholder="${H(f.ph||"")}">${H(val)}</textarea>`;break;
  case"number":inner=`<input class="fin" type="number" ${dat} value="${H(val)}" ${f.min!=null?`min="${f.min}"`:""} ${f.max!=null?`max="${f.max}"`:""} placeholder="${H(f.ph||"")}">`;break;
  case"money":inner=`<input class="fin" type="number" ${dat} value="${H(val)}" min="0" step="100">`;break;
  case"date":inner=`<input class="fin" type="date" ${dat} value="${H(val)}">`;break;
  case"range":inner=`<div class="frange"><input type="range" class="rng" ${dat} min="${f.min||0}" max="${f.max||100}" step="${f.step||1}" value="${H(val===""?(f.def||0):val)}"><b class="num" id="${id}_v">${H(val===""?(f.def||0):val)}</b></div>`;break;
  case"toggle":inner=`<button type="button" class="ftog" role="switch" aria-checked="${!!val}" data-cx-tog="${fid}:${f.k}"><i></i><span>${val?"Yes":"No"}</span></button>`;break;
  case"select":inner=`<select class="fin" ${dat}><option value="">${H(f.ph||"Choose")}</option>${opts.map(fOpt2).map(o=>`<option value="${H(o[0])}" ${String(o[0])===String(val)?"selected":""}>${H(o[1])}</option>`).join("")}</select>`;break;
  case"chips":inner=`<div class="fchips" role="radiogroup" aria-label="${H(f.label)}">${opts.map(fOpt2).map(o=>`<button type="button" class="chip" data-cx-chip="${fid}:${f.k}:${H(o[0])}" aria-pressed="${String(o[0])===String(val)}">${H(o[1])}</button>`).join("")}</div>`;break;
  case"person":case"service":case"rec":inner=`<input class="fin" type="text" ${dat} value="${H(val)}" list="${dlId(f.type)}" placeholder="${H(f.ph||(f.type==="person"?"Type a name":f.type==="service"?"Type a service":""))}" autocomplete="off">`;break;
  default:inner=`<input class="fin" type="text" ${dat} value="${H(val)}" placeholder="${H(f.ph||"")}" autocomplete="off">`}
 return`<div class="fld cx-fld ${err?"bad":""} t-${f.type||"text"}"><label class="flab" for="${id}">${H(f.label)}${f.req?'<b aria-hidden="true"> *</b>':""}${pre?'<span class="cx-pre" title="Filled by Claude from your words and the page. Check it.">Claude filled</span>':""}</label>${inner}${err?`<small class="ferr" role="alert">${H(err)}</small>`:""}${f.help?`<small class="fhelp">${H(f.help)}</small>`:""}</div>`}
function formPreview(f){const tool=TBY(f.tool);const vals=withDefaults(tool,f.vals);let h="";try{if(tool.preview)h=tool.preview(vals)||""}catch(e){}
 const c=ctxNow(findThread(f.thread));let k=null;try{k=check(tool,vals,c)}catch(e){}let g="";if(k){g=(k.gates.length&&tool.confirm==="form"?`<div class="cx-appr"><b>Approvals</b>: ${k.gates.map(x=>pchip(x.who)+'<small class="muted"> '+H(x.why)+"</small>").join(" ")}</div>`:"")+(k.block.length?`<div class="cx-err">${H(k.block[0])}</div>`:"");g+=`<div class="cx-pols">${guardChips(k.notes)}</div>`}
 return(h?`<div class="cx-prev">${san(h)}</div>`:"")+g}
function formHTML2(f){if(!f)return"";const tool=TBY(f.tool);if(!tool)return"";const vals=f.vals;const fields=inputsOf(tool,withDefaults(tool,vals)).filter(x=>!x.show||x.show(withDefaults(tool,vals)));const closed=f.status!=="open";
 if(closed)return`<div class="cx-form closed"><b>${H(tool.name)}</b> ${pillT(f.status==="done"?"Submitted":f.status==="cancelled"?"Cancelled":"Closed",f.status==="done"?"good":"mute")}</div>`;
 const catalog=tool.confirm==="form";const subj=f.vals.who&&f.vals.who!==ME_NAME?f.vals.who:null;
 return`<form class="cx-form ${catalog?"catalog":""}" data-cx-form="${f.id}" novalidate onsubmit="return false" aria-label="${H(tool.name)}"><div class="cx-fh"><b>${catalog?"Catalog: "+H(tool.name):H(tool.name)}</b>${catalog?pillT("Inline fulfillment","info"):""}${subj?pillT("For "+subj,"metric"):""}</div><div class="cx-fgrid">${fields.map(x=>fieldH(x,vals[x.k]!=null?vals[x.k]:(x.def!=null?x.def:""),f.err[x.k],f.id,(f.pre||[]).includes(x.k))).join("")}</div><div class="cx-live" data-cx-prev="${f.id}" aria-live="polite">${formPreview(f)}</div><div class="row cx-fact"><button type="button" class="btn primary" data-cx-do="form-submit:${f.id}">${catalog?"Submit order":"Review the plan"}</button><button type="button" class="btn quiet" data-cx-do="form-cancel:${f.id}">Cancel</button>${catalog?`<button type="button" class="btn quiet" data-cx-do="form-full:${f.id}">Open the full form</button>`:""}</div></form>`}
CX.redrawForm=fid=>{const el=document.querySelector(`[data-cx-form="${fid}"]`);const f=ST.forms[fid];if(!el){CX.drawMsgs&&CX.drawMsgs();return}const a=document.activeElement,aid=a&&a.id,ss=a&&a.selectionStart,se=a&&a.selectionEnd;const w=document.createElement("div");w.innerHTML=formHTML2(f);const n=w.firstElementChild;el.replaceWith(n);if(aid){const x=document.getElementById(aid);if(x){try{x.focus();if(ss!=null&&x.setSelectionRange)x.setSelectionRange(ss,se)}catch(e){}}}};
function refreshPrev(fid){const el=document.querySelector(`[data-cx-prev="${fid}"]`);if(el&&ST.forms[fid])el.innerHTML=formPreview(ST.forms[fid])}
CX.submitForm=function(fid){const f=ST.forms[fid];if(!f||f.status!=="open")return;const tool=TBY(f.tool);const vals=withDefaults(tool,f.vals);f.err={};missingOf(tool,vals).forEach(x=>f.err[x.k]="Needed");Object.assign(f.err,personValid(tool,vals));if(tool.validate){const e=G(()=>tool.validate(vals),null);if(e)Object.assign(f.err,e)}
 inputsOf(tool,vals).forEach(x=>{if(x.type==="service"&&vals[x.k]&&!SVCREG.some(s=>s.n===vals[x.k]))f.err[x.k]="Pick a service from the list"});
 if(Object.keys(f.err).length){CX.redrawForm(fid);const first=document.querySelector(`[data-cx-form="${fid}"] .fld.bad input,[data-cx-form="${fid}"] .fld.bad select,[data-cx-form="${fid}"] .fld.bad textarea`);if(first)first.focus();return}
 f.status="done";const t=findThread(f.thread);t.pend=null;const c=ctxNow(t);CX.redrawForm(fid);
 proposeAct(tool,vals,t,c,{q:f.q,conf:f.conf,forceRun:tool.confirm==="form",intro:tool.confirm==="form"?"Submitted. Here is how it is going.":"Thanks. Here is the plan from your answers."});CX.drawAll()};

/* --- messages --- */
function msgHTML(m,i){if(m.me)return`<div class="cx-m me" data-mid="${m.id}"><span class="sr">You said: </span>${H(m.t)}</div>`;
 if(m.think)return`<div class="cx-m ai think" data-mid="${m.id}"><div class="cx-thk"><i></i><i></i><i></i></div><ul class="did">${(m.steps||[]).map(s=>`<li>${H(s)}</li>`).join("")}</ul></div>`;
 const lin=m.lin?aiChipL(m.lin):"";const guards=m.lin&&m.lin.pol&&m.lin.pol.length?`<span class="cx-pc ok" title="Policies that allowed this">${H(m.lin.pol.join(", "))}</span>`:"";
 return`<div class="cx-m ai" data-mid="${m.id}"><div class="cx-txt">${san(m.t)}</div>${(m.steps||[]).length?`<details class="cx-trace"><summary>How I got there, ${m.steps.length} step${m.steps.length===1?"":"s"}</summary><ul class="did">${m.steps.map(s=>`<li>${H(s)}</li>`).join("")}</ul></details>`:""}<div class="cx-cards">${(m.cards||[]).map(c=>cardHTML(c,m)).join("")}</div><div class="row cx-foot">${lin}${guards}${m.act?`<button class="btn" data-cx-actgo="${m.id}">Take me there</button>`:""}${(m.sugg||[]).map(s=>`<button class="chip" data-cx-ask="${H(s)}">${H(s)}</button>`).join("")}</div></div>`}
function emptyHTML(t){const c=ctxNow(t);const ex=[];if(c.page&&/itsm_inc/.test(c.page.id))ex.push("Log an incident: portal is slow for editors");ex.push("Order a developer laptop for Hana Koval","Onboard Marcus Webb as a standards editor starting Oct 26","Raise my Claude token limit to 60M","How is the P1 incident SLA measured?","Who has the request for Rosa Delgado's laptop?");return`<div class="cx-m ai cx-welcome"><div class="cx-txt">Hi Casey. I can answer, and I can do things: log incidents, order from the catalog, onboard people, route approvals, raise limits. I use the page you are on and the person you act for. Try one of these, or type <b>/help</b>.</div><div class="row cx-foot">${ex.slice(0,5).map(s=>`<button class="chip" data-cx-ask="${H(s)}">${H(s)}</button>`).join("")}</div><ul class="did"><li>Context: ${H(c.page?c.page.name:"none")} as ${H(roleName())}${c.subj?" on behalf of "+H(c.subj):""}</li><li>Mode: ${H(MODES[t.mode||ST.mode].n)}</li></ul></div>`}
function streamIn(el){if(!el||DEMO_FAST()||document.documentElement.dataset.motion==="reduced"||window.matchMedia("(prefers-reduced-motion: reduce)").matches)return false;const nodes=[];const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode()))if(n.nodeValue.trim())nodes.push([n,n.nodeValue]);if(!nodes.length)return false;nodes.forEach(x=>x[0].nodeValue="");let ni=0,wi=0;const cards=el.parentElement.querySelector(".cx-cards"),foot=el.parentElement.querySelector(".cx-foot");if(cards)cards.classList.add("pend");if(foot)foot.classList.add("pend");el.parentElement.setAttribute("aria-busy","true");
 const tick=()=>{if(ni>=nodes.length){if(cards)cards.classList.remove("pend");if(foot)foot.classList.remove("pend");el.parentElement.removeAttribute("aria-busy");const lv=$("#chxLive");if(lv)lv.textContent=el.textContent;const sc=$("#msgs");if(sc)sc.scrollTop=1e6;return}const [node,full]=nodes[ni];const words=full.split(/(\s+)/);wi=Math.min(words.length,wi+5);node.nodeValue=words.slice(0,wi).join("");if(wi>=words.length){ni++;wi=0}const sc=$("#msgs");if(sc)sc.scrollTop=1e6;setTimeout(tick,28)};tick();return true}
CX.drawMsgs=function(){const box=$("#msgs");if(!box)return;const t=cur();const keepScroll=box.scrollTop,atEnd=box.scrollHeight-box.scrollTop-box.clientHeight<80;const fresh=t.msgs.filter(m=>m.ai&&m.stream&&!m.streamed&&!m.think);fresh.forEach(m=>m.streamed=true);
 box.innerHTML=(t.msgs.length?"":emptyHTML(t))+t.msgs.map(msgHTML).join("");
 if(fresh.length){const last=fresh[fresh.length-1];const el=box.querySelector(`[data-mid="${last.id}"] .cx-txt`);if(!streamIn(el)){const lv=$("#chxLive");if(lv)lv.textContent=plain(last.t)}}else{const lastAI=[...t.msgs].reverse().find(m=>m.ai&&!m.think);const lv=$("#chxLive");if(lv&&lastAI&&!lv.textContent)lv.textContent=plain(lastAI.t)}
 const lastM=t.msgs.length?box.querySelector(`[data-mid="${t.msgs[t.msgs.length-1].id}"]`):null;
 if((atEnd||fresh.length)&&lastM&&lastM.offsetHeight>box.clientHeight*.7){box.scrollTop=Math.max(0,lastM.offsetTop-box.offsetTop-8)}
 else if(atEnd||fresh.length)box.scrollTop=1e6;else box.scrollTop=keepScroll;CX.drawSugs&&CX.drawSugs()};
CX.drawSugs=function(){const el=$("#sugs");if(!el)return;const t=cur();if(CX.preSugs)try{CX.preSugs(t)}catch(e){}const last=t.msgs[t.msgs.length-1];const c=ctxNow(t);let list=[];if(!last||!last.ai){list=[c.subj?"What is on "+firstOf(c.subj)+"'s plate?":"Which approvals are waiting on me?",c.subj&&c.subj!==ME_NAME?"Show their assets and software":"Who is on call now?","Show me incidents"]}else list=(last.sugg||[]).slice(0,3);el.innerHTML=list.map(s=>`<button class="chip" data-cx-ask="${H(s)}">${H(s)}</button>`).join("")};

/* --- context strip --- */
CX.drawCtx=function(){const el=$("#chxCtx");if(!el)return;const t=cur(),c=ctxNow(t);const chips=[];
 if(c.page)chips.push(`<span class="cx-cc" title="The screen you are on. The AI can read what this page shows."><b>Page</b> ${H(c.page.name)}<button aria-label="Remove page from context" data-cx-rm="page">×</button></span>`);
 if(t.addr){const inf=addrInfo(t.addr),ac=CX.access(t);chips.push(`<span class="cx-cc to" title="${H(ADDR_KIND[t.addrType]||"Address")} address ${H(t.addr)}"><b>To</b> ${H(inf.label)} <small class="muted">${HUMAN_ADDR[t.addrType]?"simulated delivery":H((ADDR_KIND[t.addrType]||"").toLowerCase())}</small></span>`);
  if(t.ctx.rec)chips.push(`<span class="cx-cc vis ${ac.ok?"":"warn"}" title="${H(ac.why)}"><b>Visible to</b> people who can read ${H(t.ctx.rec.type)} ${H(t.ctx.rec.id)} <small class="muted">simulated check</small></span>`)}
 if(c.rec&&c.rec.thread){const r=c.rec;chips.push(`<span class="cx-cc rec" title="Kept on this thread"><b>Record</b> <button class="cx-link" data-cx-do="openrec:${H(r.id)}">${H(r.type)} ${H(r.id)}</button></span>`)}
 else if(c.rec){const r=c.rec;chips.push(`<span class="cx-cc rec" title="The last record you opened in a drawer"><b>Record</b> <button class="cx-link" data-cx-do="openrec:${H(r.id)}">${H(String(r.id).replace(/^person:/,""))}</button><button aria-label="Remove record from context" data-cx-rm="rec">×</button></span>`)}
 chips.push(`<span class="cx-cc you" title="Who is acting. Your role decides what the AI may do."><b>You</b> ${avatar(ME_NAME,{size:18})} Casey<select class="cx-sel" aria-label="Acting role and level" data-cx-role>${Object.keys(PERSONAS).map(k=>`<option value="${k}" ${k===S.persona?"selected":""}>${H(PERSONAS[k].n)}</option>`).join("")}</select></span>`);
 chips.push(c.subj?`<span class="cx-cc subj ${delegation(c.subj).verified?"":"warn"}" title="${H(delegation(c.subj).basis)}"><b>For</b> ${avatar(c.subj,{size:18})} ${H(c.subj)}${delegation(c.subj).verified?"":" (read only)"}<button aria-label="Stop acting on behalf of ${H(c.subj)}" data-cx-rm="subj">×</button></span>`:`<button class="cx-cc add" data-cx-do="pick-subj" aria-haspopup="listbox">+ Act on behalf of someone</button>`);
 c.attach.forEach(a=>chips.push(`<span class="cx-cc att" title="Attached by you"><b>${H(a.k)}</b> ${H(String(a.label).slice(0,28))}<button aria-label="Remove ${H(a.label)}" data-cx-rm="att:${H(a.k)}:${H(a.id)}">×</button></span>`));
 chips.push(`<button class="cx-cc add" data-cx-view="ctx" title="Open the context pack">+ Attach</button>`);
 el.innerHTML=chips.join("")+(c.subj?bannerHTML(c.subj):"")};

/* --- thread list --- */
CX.drawThreads=function(){const el=$("#chxThreads");if(!el)return;const q=(ST.tq||"").toLowerCase(),arch=ST.showArch;
 let L=ST.threads.filter(t=>!!t.arch===!!arch&&CX.canSee(t));if(q)L=L.filter(t=>(t.title+" "+t.msgs.map(m=>plain(m.t)).join(" ")).toLowerCase().indexOf(q)>=0);L.sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||b.upd-a.upd);
 el.innerHTML=`<div class="cx-tools"><input class="fin" type="search" id="chxTq" placeholder="Search ${ST.threads.length} threads" aria-label="Search threads" value="${H(ST.tq||"")}"><button class="btn primary" data-cx-new>New chat</button></div><div class="row"><button class="chip" data-cx-arch="0" aria-pressed="${!arch}">Active</button><button class="chip" data-cx-arch="1" aria-pressed="${!!arch}">Archived (${ST.threads.filter(t=>t.arch).length})</button></div><ul class="cx-tl">${L.map(t=>{const last=[...t.msgs].reverse().find(m=>!m.think);return`<li class="${t.id===ST.active?"on":""}"><button class="cx-tt" data-cx-th="open:${t.id}"><b>${t.pinned?"Pinned · ":""}${H(t.title)}</b><small class="muted">${last?H(plain(last.t).slice(0,70)):"Empty"}</small><span class="row"><span class="pill mute">${H(MODES[t.mode||ST.mode].n)}</span>${t.addr?`<span class="pill info">${H(ADDR_KIND[t.addrType]||"Address")}</span>`:""}${t.ctx.subj?`<span class="pill metric">For ${H(firstOf(t.ctx.subj))}</span>`:""}${t.unread?`<span class="pill info">${t.unread} new</span>`:""}<small class="muted">${ago(t.upd)}</small></span></button><div class="cx-ta"><button class="btn quiet" data-cx-th="pin:${t.id}">${t.pinned?"Unpin":"Pin"}</button><button class="btn quiet" data-cx-th="ren:${t.id}">Rename</button><button class="btn quiet" data-cx-th="${t.arch?"unarch":"arch"}:${t.id}">${t.arch?"Restore":"Archive"}</button></div></li>`}).join("")||`<li class="muted">${arch?"Nothing archived.":"No threads match."}</li>`}</ul>`};
const ago=ts=>{const m=Math.round((Date.now()-ts)/60000);return m<1?"now":m<60?m+"m":m<1440?Math.round(m/60)+"h":Math.round(m/1440)+"d"};

/* --- activities pane --- */
CX.drawActs=function(){const el=$("#chxActs");if(!el)return;const f=ST.af||"all";const A=ST.acts.filter(a=>f==="all"||(f==="run"&&(a.status==="running"))||(f==="wait"&&a.status==="awaiting"||f==="wait"&&a.status==="planned")||(f==="done"&&a.status==="done")||(f==="bad"&&["failed","cancelled","blocked","undone"].includes(a.status)));
 const cnt=k=>ST.acts.filter(a=>k==="all"||(k==="run"&&a.status==="running")||(k==="wait"&&(a.status==="awaiting"||a.status==="planned"))||(k==="done"&&a.status==="done")||(k==="bad"&&["failed","cancelled","blocked","undone"].includes(a.status))).length;
 el.innerHTML=`<div class="row cx-af">${[["all","All"],["run","Running"],["wait","Needs approval"],["done","Done"],["bad","Stopped"]].map(x=>`<button class="chip" data-cx-af="${x[0]}" aria-pressed="${f===x[0]}">${x[1]} ${cnt(x[0])}</button>`).join("")}</div>${A.length?A.map(a=>`<div class="cx-actw"><div class="row sp muted small"><span>${H(findThread(a.thread).title)} · ${ago(a.created)} ago${a.restored?" · restored (undo unavailable)":""}</span><button class="btn quiet" data-cx-th="open:${a.thread}">Open thread</button></div>${planHTML(a,{log:true})}</div>`).join(""):empty("No activities yet","Ask me to do something, such as “onboard a new editor”. Running, waiting and finished work shows here, with every approval and an undo where possible.")}`};

/* --- context pane --- */
CX.drawContext=function(){const el=$("#chxContext");if(!el)return;const t=cur(),c=ctxNow(t);const items=packItems(t);const tok=items.reduce((a,x)=>a+x.tok,0);
 const mat=c.subj?allowMatrix(c.subj,c):null;const sp=c.subj?subjectPack(c.subj):[];const caps=capsOf();
 const q=(ST.aq||"").toLowerCase();let res=[];if(q.length>1){const toks=q.split(/\s+/);let ix=[];try{ix=searchIndex()}catch(e){}res=ix.filter(r=>r.g!=="Go to"&&toks.every(x=>(r.t+" "+r.m+" "+(r.k||"")).toLowerCase().indexOf(x)>=0)).slice(0,8);const extra=[];SVCREG.filter(s=>toks.every(x=>s.n.toLowerCase().indexOf(x)>=0)).slice(0,3).forEach(s=>extra.push({g:"Service",t:s.n,m:s.tier,att:{k:"service",id:s.id,label:s.n}}));CIREG.filter(s=>toks.every(x=>s.name.toLowerCase().indexOf(x)>=0)).slice(0,3).forEach(s=>extra.push({g:"CI",t:s.name,m:s.class,att:{k:"ci",id:s.id,label:s.name}}));PROJ.filter(s=>toks.every(x=>(s.id+" "+s.n).toLowerCase().indexOf(x)>=0)).slice(0,3).forEach(s=>extra.push({g:"Project",t:s.id+" "+s.n,m:s.owner,att:{k:"project",id:s.id,label:s.id+" "+s.n}}));res=extra.concat(res.map(r=>({g:r.g,t:r.t,m:r.m,att:{k:r.g.toLowerCase(),id:r.t,label:r.t}}))).slice(0,10)}
 el.innerHTML=`<section class="cx-cs"><h4>What the AI can see right now</h4><p class="muted small">Everything below is in this thread's context pack. Remove what you do not want it to use. About ${N0(tok)} of 8,000 tokens.</p><div class="cx-tok" role="img" aria-label="${N0(tok)} of 8000 tokens used"><u style="width:${Math.min(100,tok/80)}%"></u></div><ul class="cx-pk">${items.map(x=>`<li><div><b>${H(x.label)}</b>${x.warn?' <span class="pill warn">read only</span>':""}<div class="muted small">${H(x.why)}</div><div class="muted small">Access: ${H(x.perm)} · ~${N0(x.tok)} tokens</div></div>${x.rm?`<button class="btn quiet" data-cx-rm="${H(x.rm)}" aria-label="Remove ${H(x.label)}">Remove</button>`:x.locked?'<span class="pill mute">always</span>':""}</li>`).join("")}</ul>${c.off.page||c.off.rec||c.off.kb?`<button class="btn quiet" data-cx-do="ctx-reset">Restore removed context</button>`:""}</section>
 <section class="cx-cs"><h4>Attach something</h4><p class="muted small">Add a record, service, configuration item, project or person so answers and actions use it.</p><input class="fin" type="search" id="chxAq" placeholder="Search records, services, CIs, projects" value="${H(ST.aq||"")}" aria-label="Search to attach"><ul class="cx-ar">${res.map(r=>{const k=cb(()=>{attach(r.att)});return`<li><button class="cx-link" data-cx-cb="${k}">${H(r.t)}</button><small class="muted">${H(r.g)} · ${H(r.m||"")}</small></li>`}).join("")}</ul></section>
 <section class="cx-cs"><h4>On behalf of</h4>${c.subj?bannerHTML(c.subj)+`<div class="row"><button class="btn" data-cx-do="pick-subj">Change person</button><button class="btn quiet" data-cx-rm="subj">Stop acting for them</button></div><h5>Their records</h5>${sp.filter(s=>s.n||s.redacted).map(s=>packSecHTML(s,c.subj)).join("")||'<p class="muted small">No records found.</p>'}${mat?`<h5>What I may do for them</h5><details open class="cx-sec"><summary><b>Allowed</b> <span class="pill good">${mat.ok.length}</span></summary><div class="cx-wrap">${mat.ok.map(x=>`<span class="pill good">${H(x.t.name)}</span>`).join("")}</div></details><details class="cx-sec"><summary><b>Needs approval</b> <span class="pill warn">${mat.gate.length}</span></summary>${mat.gate.map(x=>`<div class="cx-lrr"><span>${H(x.t.name)}</span><small class="muted">${x.g.length?"Approvers: "+H(x.g.map(g=>g.who).join(", ")):RISK[x.t.risk].n+" risk: a person confirms"}</small></div>`).join("")}</details><details class="cx-sec"><summary><b>Blocked</b> <span class="pill bad">${mat.no.length}</span></summary>${mat.no.map(x=>`<div class="cx-lrr"><span>${H(x.t.name)}</span><small class="muted">${H(x.why)}</small></div>`).join("")}</details>`:""}`:`<p class="muted small">Pick a person to see their assets, software, tickets, requests, projects, approvals, skills and time off, and to act for them with a verified delegation.</p><button class="btn primary" data-cx-do="pick-subj">Choose a person</button>`}</section>
 <section class="cx-cs"><h4>You and your role</h4><div class="row">${avatar(ME_NAME,{size:34})}<div><b>${H(ME_NAME)}</b><div class="muted small">Viewing as ${H(roleName())}. Switch to see what other roles may do.</div></div></div><div class="row">${Object.keys(PERSONAS).map(k=>`<button class="chip" data-cx-do="role:${k}" aria-pressed="${k===S.persona}">${H(PERSONAS[k].n)}</button>`).join("")}</div><div class="cx-wrap">${caps.map(x=>`<span class="pill mute" title="${H(CAP_LABEL[x]||x)}">${H(x)}</span>`).join("")}</div></section>
 <section class="cx-cs"><h4>Data access and permissions applied</h4><div class="tscroll"><table class="cx-tbl"><thead><tr><th>Source</th><th>Granted by</th><th>Access</th><th>Redaction</th><th>Scope</th></tr></thead><tbody>${accessRows(t).map(r=>`<tr>${r.map((x,i)=>`<td>${i===2?pillT(x,/Blocked/.test(x)?"bad":/write/i.test(x)?"warn":"good"):i===3&&x!=="None"?`<span class="cx-redact">${H(x)}</span>`:H(x)}</td>`).join("")}</tr>`).join("")}</tbody></table></div></section>`};

/* --- head, tabs, root sync --- */
const VIEWS=[["chat","Chat"],["threads","Threads"],["acts","Activities"],["ctx","Context"]];
const actBadge=()=>ST.acts.filter(a=>a.status==="running"||a.status==="awaiting"||a.status==="planned").length;
const mineWaiting=()=>{let n=0;ST.acts.forEach(a=>{if(["awaiting","planned"].includes(a.status))a.steps.forEach(s=>{if(s.kind==="gate"&&s.status==="awaiting"&&s.gate.who===ME_NAME)n++});if(a.status==="planned")n++});ST.reqs.forEach(r=>{if(r.state==="Approvals")r.gates.forEach(g=>{if(g.st==="pending"&&g.who===ME_NAME)n++})});return n};
CX.badge=function(){const n=mineWaiting()+ST.threads.reduce((a,t)=>a+(t.unread||0),0);const b=$("#chxBadge");if(b){b.textContent=n?String(n):"";b.hidden=!n}const ab=$("#chxActBadge");if(ab){const k=actBadge();ab.textContent=k?String(k):"";ab.hidden=!k}};
CX.drawHead=function(){const t=cur();const h=$("#chxTitle");if(h&&document.activeElement!==h)h.textContent=t.title;const tabs=$("#chxTabs");if(tabs)tabs.innerHTML=VIEWS.map(v=>`<button role="tab" class="cx-tab" data-cx-view="${v[0]}" aria-selected="${ST.dock.full&&window.innerWidth>=1250?(v[0]===ST.dock.side):ST.dock.view===v[0]}" id="cxtab-${v[0]}">${v[1]}${v[0]==="acts"?'<b class="cx-nb" id="chxActBadge" hidden></b>':v[0]==="threads"?`<b class="cx-nb">${ST.threads.filter(x=>!x.arch).length}</b>`:""}</button>`).join("");const ms=$("#chxMode");if(ms)ms.value=t.mode||ST.mode;CX.badge()};
function syncRoot(){const r=document.documentElement,open=CX.isOpen();r.classList.toggle("chx-open",open);r.classList.toggle("chx-full",open&&!!ST.dock.full);r.style.setProperty("--chxw",Math.max(340,Math.min(ST.dock.w,Math.floor(window.innerWidth*.6)))+"px");const rail=$(".rail");const rr=rail?rail.getBoundingClientRect():null;r.style.setProperty("--chx-left",(rr&&rr.right>0&&window.innerWidth>900?Math.round(rr.right+18):14)+"px");const d=$("#chatDock");if(d){d.dataset.view=ST.dock.view;d.dataset.side=ST.dock.side||"ctx"}const o=$("#chxOrb");if(o)o.setAttribute("aria-expanded",String(open));const fb=$("#chxFull");if(fb){fb.textContent=ST.dock.full?"Exit full screen":"Full screen";fb.setAttribute("aria-pressed",String(!!ST.dock.full))}}
CX.isOpen=()=>{const c=$("#chatOpen");return!!(c&&c.checked)};
CX.open=function(view){const c=$("#chatOpen");if(!c)return;const was=c.checked;c.checked=true;if(view)ST.dock.view=view;cur().unread=0;syncRoot();CX.drawAll();if(!was||view==="chat"){setTimeout(()=>{const i=$("#chatq");if(i&&ST.dock.view==="chat"&&!CX.noFocus)i.focus({preventScroll:true})},60)}saveSoon()};
CX.close=function(){const c=$("#chatOpen");if(c)c.checked=false;syncRoot();const o=$("#chxOrb");if(o&&!CX.noFocus)o.focus({preventScroll:true});saveSoon()};
CX.toggle=()=>CX.isOpen()?CX.close():CX.open("chat");
CX.full=function(on){ST.dock.full=on==null?!ST.dock.full:!!on;if(ST.dock.full&&!CX.isOpen())$("#chatOpen").checked=true;syncRoot();CX.drawAll();saveSoon()};
CX.drawAll=function(){CX.drawHead();CX.drawCtx();CX.drawMsgs();CX.drawThreads();CX.drawActs();CX.drawContext();syncRoot();if(CX.afterDraw)try{CX.afterDraw()}catch(e){}};
let _rf=0;CX.refresh=function(){if(_rf)return;_rf=requestAnimationFrame(()=>{_rf=0;
 document.querySelectorAll("[data-cx-act]").forEach(el=>{const a=CX.actById(el.dataset.cxAct);if(!a)return;const inActs=el.closest("#chxActs");const w=document.createElement("div");w.innerHTML=planHTML(a,{log:!!inActs});const n=w.firstElementChild;if(n&&n.outerHTML!==el.outerHTML){const open=[...el.querySelectorAll("details[open]")].map(d=>d.querySelector("summary").textContent);el.replaceWith(n);n.querySelectorAll("details").forEach(d=>{if(open.includes(d.querySelector("summary").textContent))d.open=true})}});
 document.querySelectorAll("[data-cx-req]").forEach(el=>{const id=el.dataset.cxReq;const r=ST.reqs.find(x=>x.id===id);if(!r)return;const w=document.createElement("div");w.innerHTML=trackHTML({id});const n=w.firstElementChild;if(n&&n.outerHTML!==el.outerHTML)el.replaceWith(n)});
 if(!document.activeElement||!document.activeElement.closest||!document.activeElement.closest("#chxActs"))CX.drawActs();CX.drawHead();CX.drawThreads();try{CX.updateHome&&CX.updateHome()}catch(e){}})};

/* --- person picker --- */
function pickerHTML(q){const toks=(q||"").toLowerCase().split(/\s+/).filter(Boolean);const rec=ST.recentS||[];let L=DIR.filter(d=>d.name!==ME_NAME&&d.kind!=="ai"&&(!toks.length||toks.every(t=>(d.name+" "+d.role+" "+d.team+" "+(d.skills||[]).join(" ")).toLowerCase().indexOf(t)>=0)));const tot=L.length;if(!toks.length)L=L.filter(d=>rec.indexOf(d.name)>=0).sort((a,b)=>rec.indexOf(a.name)-rec.indexOf(b.name)).concat(L.filter(d=>rec.indexOf(d.name)<0));L=L.slice(0,14);
 const row=d=>{const dl=delegation(d.name);return`<li><button role="option" data-cx-do="subj:${H(d.name)}">${avatar(d,{size:32})}<span class="cx-pn"><b>${H(d.name)}</b><small class="muted">${H(d.role||"")}${d.team?" · "+H(d.team):""}</small></span>${kindPill(d.kind)}${dl.verified?"":'<span class="pill warn" title="No verified delegation: you can read their public records but not change anything">No delegation</span>'}</button></li>`};
 return(L.map(row).join("")||'<li class="muted" style="padding:8px">No one matches.</li>')+(tot>L.length?'<li class="muted small" style="padding:6px 8px">Showing '+L.length+' of '+N0(tot)+'. Type to narrow the list.</li>':"")}
CX.openPicker=function(){let el=$("#chxPicker");if(!el){el=document.createElement("div");el.id="chxPicker";el.className="cx-picker glass";el.setAttribute("role","dialog");el.setAttribute("aria-label","Choose who to act for");$("#chatDock").appendChild(el)}el.hidden=false;el.innerHTML=`<div class="row sp"><b>Act on behalf of</b><button class="btn quiet" data-cx-do="close-picker">Close</button></div><input class="fin" type="search" id="chxPq" placeholder="Search ${DIR.length} people by name, role, team or skill" aria-label="Search people" autocomplete="off"><ul class="cx-pl" role="listbox" id="chxPl">${pickerHTML("")}</ul><p class="muted small">Delegation is checked as you pick. Without one, I can read their public records but not change anything.</p>`;setTimeout(()=>{const i=$("#chxPq");if(i)i.focus()},30)};

/* ================= commands and events ================= */
function doCmd(d){const p=d.split(":");const k=p[0];const rest=d.slice(k.length+1);
 if(k==="go"){go(p[1],p[2]);return}
 if(k==="ask"){handle(rest);return}
 if(k==="tool"){runTool(p[1],decodeURIComponent(p.slice(2).join(":")));return}
 if(k==="person"){person360(rest);return}
 if(k==="subj"){ST.recentS=[rest].concat((ST.recentS||[]).filter(x=>x!==rest)).slice(0,5);setSubject(rest);return}
 if(k==="impact"){G(()=>openImpact({type:p[1],id:p[2],service:p[3]||undefined,ci:p[4]||undefined}));return}
 if(k==="slaopen"){go("svc_sla");G(()=>SLAX.openAg(rest));return}
 if(k==="reqopen"){go("svc_req");G(()=>svcOpenRequest(rest));return}
 if(k==="openrec"){openRec(rest);return}}
function openRec(id){if(/^person:/.test(id)){person360(id.slice(7));return}const r=lookupRec(id);if(r&&r.go)r.go();else toast("Cannot open "+id,"warn")}
function setPersona(k){if(!PERSONAS[k])return;S.persona=k;savePrefs();audit("switched role from chat",PERSONAS[k].n);if(!SCREENS.some(s=>s[0]===S.screen))S.screen="home";try{render()}catch(e){}CX.drawAll()}
function editAct(a){const tool=TBY(a.tool);if(!tool)return;a.status="cancelled";a.steps.forEach(s=>{if(s.status==="queued")s.status="cancelled"});logA(a,"Edited: replaced by a new plan");const t=findThread(a.thread);const fid=uid("F");ST.forms[fid]={id:fid,tool:tool.id,vals:Object.assign({},a.params),err:{},pre:Object.keys(a.params||{}),status:"open",thread:t.id,q:a.q,conf:a.conf,created:Date.now()};sayAI(t,"Change what you like. I will re-check the guardrails and rebuild the plan.",{cards:[{t:"form",id:fid}],stream:false});CX.drawAll()}
function escalate(a){const t=findThread(a.thread);const task={id:"CT"+(ST.tasks.length+1),t:"Review chat activity: "+a.title,own:"Tom Becker",team:"Service desk",due:addD(TODAY,1),st:"open"};ST.tasks.unshift(task);ST.use.esc++;audit("chat: handed to a person",a.title+" → "+task.id);logA(a,"Handed to the service desk lead as "+task.id);sayAI(t,"I handed this to <b>Tom Becker</b> on the service desk as task "+task.id+". He will see the plan, what ran and what stopped.",{cards:[{t:"btnrow",btns:[{l:"Open Person 360",d:"person:Tom Becker"}]}],stream:false});CX.refresh()}
function retryAct(a){a.steps.forEach(s=>{if(s.status==="failed"||s.status==="blocked"){s.status="queued";s.err="";s.blocked=[]}});a.blocked=[];a.status="planned";runAct(a)}
document.addEventListener("click",e=>{const t=e.target.closest("[data-cx-do],[data-cx-cmd],[data-cx-ask],[data-cx-view],[data-cx-new],[data-cx-th],[data-cx-rm],[data-cx-cb],[data-cx-chip],[data-cx-tog],[data-cx-arch],[data-cx-af],[data-cx-actgo],[data-cx-full],[data-cx-hide],[data-cx-pol],[data-cx-capt],[data-cx-tab]");if(!t||!document.getElementById("chatDock"))return;const d=t.dataset;
 if(d.cxCmd!=null){doCmd(d.cxCmd);return}
 if(d.cxAsk!=null){handle(d.cxAsk);return}
 if(d.cxCb){const f=CBS.get(d.cxCb);if(f)f();return}
 if(d.cxActgo){const m=cur().msgs.find(x=>x.id===d.cxActgo);if(m&&m.act)m.act();return}
 if(d.cxView){if(ST.dock.full&&(d.cxView==="acts"||d.cxView==="ctx"))ST.dock.side=d.cxView;ST.dock.view=d.cxView;if(d.cxView==="ctx")CX.drawContext();CX.drawHead();syncRoot();if(d.cxView==="chat")setTimeout(()=>{const i=$("#chatq");if(i)i.focus()},40);return}
 if(d.cxNew!=null){newThread();CX.open("chat");return}
 if(d.cxFull!=null){CX.full();return}if(d.cxHide!=null){CX.close();return}
 if(d.cxArch!=null){ST.showArch=d.cxArch==="1";CX.drawThreads();return}
 if(d.cxAf){ST.af=d.cxAf;CX.drawActs();return}
 if(d.cxTh){const [k,id]=[d.cxTh.slice(0,d.cxTh.indexOf(":")),d.cxTh.slice(d.cxTh.indexOf(":")+1)];const th=ST.threads.find(x=>x.id===id);if(!th)return;
  if(k==="open"){ST.active=id;th.unread=0;ST.dock.view="chat";CX.open("chat");return}
  if(k==="pin"){th.pinned=!th.pinned;audit("chat: "+(th.pinned?"pinned":"unpinned")+" thread",th.title)}
  if(k==="arch"){th.arch=true;audit("chat: archived thread",th.title);if(ST.active===id)ST.active=null;cur()}
  if(k==="unarch"){th.arch=false}
  if(k==="ren"){const n=window.prompt?null:null;ST.ren=id;CX.drawThreads();const li=document.querySelector('[data-cx-th="open:'+id+'"] b');if(li){li.contentEditable="true";li.focus();const rg=document.createRange();rg.selectNodeContents(li);const sel=getSelection();sel.removeAllRanges();sel.addRange(rg);const fin=()=>{li.contentEditable="false";const v=li.textContent.trim();if(v){th.title=v.replace(/^Pinned · /,"");th.manual=true;audit("chat: renamed thread",th.title)}ST.ren=null;CX.drawAll();saveSoon()};li.addEventListener("blur",fin,{once:true});li.addEventListener("keydown",ev=>{if(ev.key==="Enter"){ev.preventDefault();li.blur()}})}return}
  CX.drawAll();saveSoon();return}
 if(d.cxRm){const k=d.cxRm,th=cur();if(k==="page"||k==="rec"||k==="kb")th.ctx.off[k]=true;else if(k==="subj")setSubject(null);else if(/^att:/.test(k)){const [,kk,...r]=k.split(":");const id=r.join(":");th.ctx.attach=th.ctx.attach.filter(a=>!(a.k===kk&&a.id===id))}audit("chat: removed from context",k);CX.drawAll();saveSoon();return}
 if(d.cxChip){const [fid,k,...v]=d.cxChip.split(":");const f=ST.forms[fid];if(!f)return;f.vals[k]=v.join(":");delete f.err[k];CX.redrawForm(fid);return}
 if(d.cxTog){const [fid,k]=d.cxTog.split(":");const f=ST.forms[fid];f.vals[k]=!f.vals[k];CX.redrawForm(fid);return}
 if(d.cxPol){const [id,k]=d.cxPol.split(":");const p=pol(id);if(p.lock){toast(id+" cannot be switched off","warn");return}p.on=!p.on;audit("chat guardrail edited",id+" "+p.n+" → "+(p.on?"on":"off"));saveSoon();try{render()}catch(e){};return}
 if(d.cxCapt){const [r,c]=d.cxCapt.split("|");ST.permOv[r]=ST.permOv[r]||{};const has=capsOf(r).includes(c);ST.permOv[r][c]=!has;audit("chat permission edited",r+" "+c+" → "+(!has?"granted":"revoked"));saveSoon();try{render()}catch(e){};return}
 if(d.cxDo){const p=d.cxDo.split(":");const k=p[0];const A=id=>CX.actById(id);
  if(k==="plan-run"){const a=A(p[1]);if(a&&a.status==="planned"){a.approved=ME_NAME;logA(a,"Approved by "+ME_NAME+" ("+a.mode+" mode)");audit("chat: approved plan",a.title);runAct(a)}return}
  if(k==="plan-edit"){editAct(A(p[1]));return}
  if(k==="plan-cancel"){const a=A(p[1]);if(a){if(a.status==="planned"||a.status==="suggested"){a.status="cancelled";a.steps.forEach(s=>s.status="cancelled");logA(a,"Cancelled before running");audit("chat: cancelled plan",a.title);CX.refresh()}else cancelAct(a)}return}
  if(k==="plan-undo"){undoAct(A(p[1]));return}
  if(k==="plan-retry"){retryAct(A(p[1]));return}
  if(k==="plan-escalate"){escalate(A(p[1]));return}
  if(k==="plan-open"){ST.af="all";CX.open("acts");return}
  if(k==="plan-ask"){const a=A(p[1]);const th=findThread(a.thread);th.mode="ask";a.mode="ask";a.status="planned";CX.drawAll();return}
  if(k==="gate"){const a=A(p[1]);if(a)gateDecide(a,p[2],p[3],p[4]==="demo"?"demo":p[4]==="me"?"me":undefined);return}
  if(k==="nudge"){toast("Nudge sent to the approver in Teams","info");audit("chat: nudged approver",p[1]);return}
  if(k==="reqgate"){reqGate(p[1],+p[2],p[3],p[4]==="demo"?"demo":undefined);return}
  if(k==="deliver"){const r=ST.reqs.find(x=>x.id===p[1]);if(r){r.state="Delivered";r.log.push({t:clock(),tx:"Delivered and confirmed (demo)"});G(()=>{const x=S.itsm.req.find(y=>y.id===r.id);if(x)x.st="good"});audit("chat: request delivered",r.id);CX.refresh()}return}
  if(k==="form-submit"){CX.submitForm(p[1]);return}
  if(k==="form-cancel"){const f=ST.forms[p[1]];if(f){f.status="cancelled";const th=findThread(f.thread);th.pend=null;CX.redrawForm(f.id)}return}
  if(k==="form-full"){const f=ST.forms[p[1]];if(f){const th=findThread(f.thread);G(()=>{go("svc_portal");_askPrev(f.q)})}return}
  if(k==="role"){setPersona(p[1]);return}
  if(k==="pick-subj"){CX.openPicker();return}
  if(k==="close-picker"){const el=$("#chxPicker");if(el)el.hidden=true;return}
  if(k==="subj"){const n=d.cxDo.slice(5);ST.recentS=[n].concat((ST.recentS||[]).filter(x=>x!==n)).slice(0,5);setSubject(n);const el=$("#chxPicker");if(el)el.hidden=true;return}
  if(k==="deleg-request"){const n=d.cxDo.slice(14);ST.deleg.push({id:"DL"+(ST.deleg.length+1),from:n,to:ME_NAME,scope:"Orders, tickets, approvals",by:n,until:addD(TODAY,90),why:"Requested from chat (demo: granted at once)"});audit("chat: delegation requested and granted (demo)",n);toast(firstOf(n)+" granted a delegation (demo)","good");CX.drawAll();return}
  if(k==="ctx-reset"){cur().ctx.off={};CX.drawAll();return}
  if(k==="openrec"){openRec(d.cxDo.slice(8));return}
  if(k==="test-run"){const i=$("#cxTq");if(i){ST.tc=i.value;try{render()}catch(e){}}return}
  if(k==="test-suite"){CX.suite=CX.runSuite();try{render()}catch(e){}return}
  if(k==="test-chat"){handle(ST.tc||"");return}
  return}});
document.addEventListener("input",e=>{const t=e.target;if(!t.dataset)return;
 if(t.dataset.cxF){const [fid,k]=t.dataset.cxF.split(":");const f=ST.forms[fid];if(!f)return;f.vals[k]=t.type==="number"&&t.value!==""?+t.value:t.value;if(f.err[k]){delete f.err[k];const fl=t.closest(".fld");if(fl){fl.classList.remove("bad");const er=fl.querySelector(".ferr");if(er)er.remove()}}if(t.type==="range"){const o=document.getElementById(t.id+"_v");if(o)o.textContent=t.value}clearTimeout(f._pv);f._pv=setTimeout(()=>refreshPrev(fid),120);return}
 if(t.id==="chxTq"){ST.tq=t.value;const i=t.selectionStart;CX.drawThreads();const n=$("#chxTq");if(n){n.focus();n.setSelectionRange(i,i)}return}
 if(t.id==="chxAq"){ST.aq=t.value;const i=t.selectionStart;CX.drawContext();const n=$("#chxAq");if(n){n.focus();n.setSelectionRange(i,i)}return}
 if(t.id==="chxPq"){$("#chxPl").innerHTML=pickerHTML(t.value);return}
 if(t.id==="chatq"){slashMenu(t.value);return}
 if(t.id==="cxTq"){ST.tc=t.value}});
document.addEventListener("change",e=>{const t=e.target;if(!t.dataset)return;
 if(t.dataset.cxF){const [fid,k]=t.dataset.cxF.split(":");const f=ST.forms[fid];if(!f)return;f.vals[k]=t.type==="number"&&t.value!==""?+t.value:t.value;if(t.tagName==="SELECT")CX.redrawForm(fid);else refreshPrev(fid);return}
 if(t.dataset.cxRole!=null){setPersona(t.value);return}
 if(t.id==="chxMode"){const th=cur();th.mode=t.value;audit("chat: autonomy changed",MODES[t.value].n+" in "+th.title);CX.drawAll();return}
 if(t.dataset.cxPolv){const p=pol(t.dataset.cxPolv);p.val=+t.value;audit("chat guardrail edited",p.id+" "+p.n+" → "+p.val);saveSoon();return}
 if(t.dataset.cxDefmode!=null){ST.mode=t.value;audit("chat: default autonomy",t.value);saveSoon();return}});
document.addEventListener("dblclick",e=>{const h=e.target.closest("#chxTitle");if(!h)return;h.contentEditable="true";h.focus();const fin=()=>{h.contentEditable="false";const v=h.textContent.trim();if(v){cur().title=v;cur().manual=true;audit("chat: renamed thread",v)}CX.drawAll();saveSoon()};h.addEventListener("blur",fin,{once:true});h.addEventListener("keydown",ev=>{if(ev.key==="Enter"){ev.preventDefault();h.blur()}})});
